from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar('T')


class Option(Generic[T]):
    pass


@dataclass
class Some(Option[T]):
    value: T


class NoneOption(Option[T]):
    pass


def divide(dividend: float, divisor: float) -> Option[float]:
    if divisor == 0:
        return NoneOption()
    return Some(dividend / divisor)


def print_result(result: Option[float]) -> None:
    match result:
        case Some(value):
            print(f"Result: {value}")
        case NoneOption():
            print("Error: Division by zero")


def main():
    result1 = divide(10, 2)
    result2 = divide(10, 0)

    print_result(result1)
    print_result(result2)


if __name__ == "__main__":
    main()

