import sys
from enum import Enum, auto
from functools import wraps
from pathlib import Path
from typing import Callable, Any, Set, TypeVar

R = TypeVar('R')

class Effect(Enum):
    IO = auto()
    FILESYSTEM = auto()

def has_effects(*effects: Effect) -> Callable[[Callable[..., R]], Callable[..., R]]:
    def decorator(func: Callable[..., R]) -> Callable[..., R]:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> R:
            return func(*args, **kwargs)
        setattr(wrapper, '__effects__', set(effects))
        return wrapper
    return decorator

def computeSum(a: int, b: int) -> int:
    return a + b

@has_effects(Effect.IO)
def printSum(a: int, b: int) -> None:
    result = computeSum(a, b)
    print(f"Sum: {result}")

@has_effects(Effect.IO, Effect.FILESYSTEM)
def logToFile(filename: str, message: str) -> None:
    try:
        Path(filename).write_text(message + "\n")
    except IOError as e:
        print(f"Error writing to file: {e}", file=sys.stderr)

def main() -> None:
    result = computeSum(10, 20)
    printSum(10, 20)
    logToFile("output.txt", f"Sum was {result}")
    print("Done")

if __name__ == "__main__":
    main()

