from dataclasses import dataclass
from typing import Generic, TypeVar, Union

T = TypeVar('T')
E = TypeVar('E')

@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T

@dataclass(frozen=True)
class Err(Generic[E]):
    message: E

Result = Union[Ok[T], Err[E]]

def parse_int(s: str) -> Result[int, str]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int, str]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main():
    # Test case 1: parse_int("10") then divide by 2 -> "Result: 5"
    result = parse_int("10")
    if isinstance(result, Ok):
        final_result = divide_safe(result.value, 2)
    else:
        final_result = result

    if isinstance(final_result, Ok):
        print(f"Result: {final_result.value}")
    else:
        print(f"Error: {final_result.message}")

    # Test case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    result = parse_int("10")
    if isinstance(result, Ok):
        final_result = divide_safe(result.value, 0)
    else:
        final_result = result

    if isinstance(final_result, Ok):
        print(f"Result: {final_result.value}")
    else:
        print(f"Error: {final_result.message}")

    # Test case 3: parse_int("abc") -> "Error: Invalid integer"
    final_result = parse_int("abc")
    # The chain short-circuits, so we don't attempt division
    if isinstance(final_result, Ok):
        print(f"Result: {final_result.value}")
    else:
        print(f"Error: {final_result.message}")


if __name__ == "__main__":
    main()

