from dataclasses import dataclass
from typing import Union, final

@final
@dataclass(frozen=True)
class Pending:
    pass

@final
@dataclass(frozen=True)
class InProgress:
    pass

@final
@dataclass(frozen=True)
class Completed:
    pass

Status = Union[Pending, InProgress, Completed]

def describeStatus(status: Status) -> str:
    match status:
        case Pending():
            return "Waiting to start"
        case InProgress():
            return "Currently working"
        case Completed():
            return "All done"

def main() -> None:
    pending_status = Pending()
    in_progress_status = InProgress()
    completed_status = Completed()

    statuses = [pending_status, in_progress_status, completed_status]

    for s in statuses:
        print(describeStatus(s))

if __name__ == "__main__":
    main()

