#!/usr/bin/env python3

"""
A program that prints the FizzBuzz sequence from 1 to 100.
"""

from typing import List


def generate_fizzbuzz(limit: int) -> List[str]:
    """
    Generates a list of FizzBuzz strings up to a given limit.

    Args:
        limit: The upper bound (inclusive) for the sequence.

    Returns:
        A list of strings representing the FizzBuzz sequence.
    """
    result: List[str] = []
    for i in range(1, limit + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result


def main() -> None:
    """
    Main function to print the FizzBuzz sequence.
    """
    fizzbuzz_sequence = generate_fizzbuzz(100)
    for item in fizzbuzz_sequence:
        print(item)


if __name__ == "__main__":
    main()

