type Term = TVar(string) | TLam(string, Term) | TApp(Term, Term)

func subst(term: Term, varName: string, replacement: Term) -> Term =
  match term {
    TVar(name) => if name == varName then replacement else term,
    TLam(param, body) => if param == varName then term else TLam(param, subst(body, varName, replacement)),
    TApp(f, a) => TApp(subst(f, varName, replacement), subst(a, varName, replacement))
  }

func eval(term: Term) -> Term =
  match term {
    TVar(_) => term,
    TLam(_, _) => term,
    TApp(f, a) =>
      let vf = eval(f) in
      match vf {
        TLam(param, body) =>
          let va = eval(a) in
          eval(subst(body, param, va)),
        _ =>
          let va = eval(a) in
          TApp(vf, va)
      }
  }

func showTerm(t: Term) -> string =
  match t {
    TVar(name) => name,
    TLam(param, body) => "(\\" ++ param ++ ". " ++ showTerm(body) ++ ")",
    TApp(f, a) => "(" ++ showTerm(f) ++ " " ++ showTerm(a) ++ ")"
  }

