from __future__ import annotations
import dataclasses
from typing import Union

@dataclasses.dataclass
class TVar:
    name: str

@dataclasses.dataclass
class TLam:
    param: str
    body: Term

@dataclasses.dataclass
class TApp:
    func: Term
    arg: Term

Term = Union[TVar, TLam, TApp]

def subst(term: Term, var_name: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        if term.name == var_name:
            return replacement
        else:
            return term
    elif isinstance(term, TLam):
        if term.param == var_name:
            # The variable is shadowed by the lambda parameter, so no substitution inside.
            return term
        else:
            # Substitute inside the body.
            return TLam(term.param, subst(term.body, var_name, replacement))
    elif isinstance(term, TApp):
        # Substitute in both the function and the argument.
        return TApp(
            subst(term.func, var_name, replacement),
            subst(term.arg, var_name, replacement)
        )
    else:
        # This should be unreachable if all Term types are handled.
        raise TypeError(f"Unhandled term type: {type(term)}")

def eval_term(term: Term) -> Term:
    if isinstance(term, TApp):
        # Evaluate the function part.
        func_val = eval_term(term.func)
        # Evaluate the argument part (call-by-value).
        arg_val = eval_term(term.arg)

        if isinstance(func_val, TLam):
            # Beta-reduction: substitute the argument into the lambda body.
            new_body = subst(func_val.body, func_val.param, arg_val)
            # Evaluate the resulting term.
            return eval_term(new_body)
        else:
            # If the function part doesn't evaluate to a lambda, it's a stuck term.
            return TApp(func_val, arg_val)
    else:
        # Variables and Lambdas are values, they evaluate to themselves.
        return term

def main():
    # Represents (λx. λy. x) 1 2
    # The K combinator (const function) applied to 1 and 2.
    expr = TApp(
        TApp(
            TLam("x", TLam("y", TVar("x"))),
            TVar("1")
        ),
        TVar("2")
    )

    result = eval_term(expr)
    print(result)

if __name__ == "__main__":
    main()

