  }

pure func allAlpha(cs: [string]) -> bool =
  match cs {
    [] => true,
    c :: rest => if c >= "a" && c <= "z" then allAlpha(rest) else false
  }

pure func isLowerAlpha(s: string) -> bool {
  let cs = chars(s);
  match cs {
    [] => false,
    _ => allAlpha(cs)
  }
}

pure func extractUser(msg: string) -> Option[string] {
  let parts = split(msg, ": ");
  match last(parts) {
    Some(seg) => if isLowerAlpha(seg) then Some(seg) else None,
    None => None
  }
}

pure func process(lines: [string], info: int, err: int, warn: int, users: [string]) -> {info: int, err: int, warn: int, users: [string]} =
  match lines {
    [] => {info: info, err: err, warn: warn, users: users},
    line :: rest => {
      let tokens = split(line, " ");
      let level = match nth(tokens, 2) { Some(lv) => lv, None => "" };
      let msgTokens = drop(3, tokens);
      let msg = join(" ", msgTokens);
      let info2 = if level == "INFO" then info + 1 else info;
      let err2 = if level == "ERROR" then err + 1 else err;
      let warn2 = if level == "WARNING" then warn + 1 else warn;
      let users2 = match extractUser(msg) {
        Some(u) => if containsUser(u, users) then users else u :: users,
        None => users
      };
      process(rest, info2, err2, warn2, users2)
    }
  }

