from dataclasses import dataclass
from typing import List, Tuple, Union

@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Let:
    var_name: str
    value_expr: 'Expr'
    body_expr: 'Expr'

Expr = Union[Num, Var, Add, Mul, Let]
Environment = List[Tuple[str, int]]

def lookup(name: str, env: Environment) -> int:
    """Finds the value of a variable in the environment."""
    for var_name, value in reversed(env):
        if var_name == name:
            return value
    raise NameError(f"Variable '{name}' not found in environment.")

def evaluate(expr: Expr, env: Environment) -> int:
    """Evaluates an expression in a given environment."""
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        left_val = evaluate(expr.left, env)
        right_val = evaluate(expr.right, env)
        return left_val + right_val
    elif isinstance(expr, Mul):
        left_val = evaluate(expr.left, env)
        right_val = evaluate(expr.right, env)
        return left_val * right_val
    elif isinstance(expr, Let):
        value = evaluate(expr.value_expr, env)
        new_env = env + [(expr.var_name, value)]
        return evaluate(expr.body_expr, new_env)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

def main():
    """Defines the program and evaluates it."""
    # AST for: let x = 5 in let y = x + 3 in x * y
    program_ast = Let(
        "x",
        Num(5),
        Let(
            "y",
            Add(Var("x"), Num(3)),
            Mul(Var("x"), Var("y"))
        )
    )

    initial_env: Environment = []
    result = evaluate(program_ast, initial_env)
    print(result)

if __name__ == "__main__":
