from dataclasses import dataclass
from typing import TypeVar, Generic, Callable, List

T = TypeVar('T')
U = TypeVar('U')


@dataclass
class Some(Generic[T]):
    value: T


class NoneType:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance


Option = Some[T] | NoneType


def findFirst(predicate: Callable[[T], bool], lst: List[T]) -> Option[T]:
    for element in lst:
        if predicate(element):
            return Some(element)
    return NoneType()


def mapOption(fn: Callable[[T], U], option: Option[T]) -> Option[U]:
    if isinstance(option, Some):
        return Some(fn(option.value))
    return NoneType()


def main():
    is_even = lambda x: x % 2 == 0
    double = lambda x: x * 2

    list1 = [1, 2, 3, 4, 5]
    result1 = findFirst(is_even, list1)
    result1 = mapOption(double, result1)

    if isinstance(result1, Some):
        print(f"Found: {result1.value}")
