type Color = Red | Black

type RBTree = Empty | Node(Color, RBTree, int, RBTree)

pure func balance(c: Color, left: RBTree, val: int, right: RBTree) -> RBTree =
  match c {
    Black => match left {
      Node(Red, Node(Red, a, x, b), y, c_tree) => 
        Node(Red, Node(Black, a, x, b), y, Node(Black, c_tree, val, right)),
      Node(Red, a, x, Node(Red, b, y, c_tree)) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c_tree, val, right)),
      _ => match right {
        Node(Red, Node(Red, b, y, c_tree), z, d) =>
          Node(Red, Node(Black, left, val, b), y, Node(Black, c_tree, z, d)),
        Node(Red, b, y, Node(Red, c_tree, z, d)) =>
          Node(Red, Node(Black, left, val, b), y, Node(Black, c_tree, z, d)),
        _ => Node(c, left, val, right)
      }
    },
    Red => Node(c, left, val, right)
  }

pure func ins(x: int, tree: RBTree) -> RBTree =
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(c, left, val, right) =>
      if x < val then balance(c, ins(x, left), val, right)
      else if x > val then balance(c, left, val, ins(x, right))
      else tree
  }

pure func makeBlack(tree: RBTree) -> RBTree =
  match tree {
    Empty => Empty,
    Node(_, left, val, right) => Node(Black, left, val, right)
  }

pure func insert(x: int, tree: RBTree) -> RBTree =
  makeBlack(ins(x, tree))

pure func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, left, val, right) => inorder(left) ++ [val] ++ inorder(right)
  }

pure func insertAll(xs: [int], tree: RBTree) -> RBTree =
  match xs {
    [] => tree,
    x :: rest => insertAll(rest, insert(x, tree))
  }

pure func showList(xs: [int]) -> string =
  match xs {
    [] => "",
    [x] => show(x),
    x :: rest => show(x) ++ ", " ++ showList(rest)
  }

export func main() -> () ! {IO} {
  let values = [7, 3, 18, 10, 22, 8, 11, 26];
  let tree = insertAll(values, Empty);
  let sorted = inorder(tree);
  println("[" ++ showList(sorted) ++ "]")
}

