  match event {
    Reset => Green(20),
    Tick => match state {
      Green(t) => if t > 1 then Green(t - 1) else Yellow(3),
      Yellow(t) => if t > 1 then Yellow(t - 1) else Red(10),
      Red(t) => if t > 1 then Red(t - 1) else Green(20)
    }
  }

func runTicks(state: State, count: int) -> State ! {IO} =
  if count == 0 then state else {
    let next = transition(state, Tick);
    println(display(next));
    runTicks(next, count - 1)
  }

export func main() -> () ! {IO} {
  let start = Green(20);
  let afterTicks = runTicks(start, 25);
  let resetState = transition(afterTicks, Reset);
  println(display(resetState));
  let _ = runTicks(resetState, 5);
  ()
}

