type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

pure func diff(e: Expr, v: string) -> Expr =
  match e {
    Const(_) => Const(0),
    Var(name) => if name == v then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, v), diff(b, v)),
    Mul(a, b) => Add(Mul(a, diff(b, v)), Mul(b, diff(a, v)))
  }

pure func simplify(e: Expr) -> Expr =
  match e {
    Const(n) => Const(n),
    Var(name) => Var(name),
    Add(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), e2) => e2,
        (e1, Const(0)) => e1,
        (Const(n1), Const(n2)) => Const(n1 + n2),
        _ => Add(sa, sb)
      }
    },
    Mul(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), e2) => e2,
        (e1, Const(1)) => e1,
        (Const(n1), Const(n2)) => Const(n1 * n2),
        _ => Mul(sa, sb)
      }
    }
  }

pure func showExpr(e: Expr) -> string =
  match e {
    Const(n) => show(n),
    Var(name) => name,
    Add(a, b) => "(" ++ showExpr(a) ++ " + " ++ showExpr(b) ++ ")",
    Mul(a, b) => "(" ++ showExpr(a) ++ " * " ++ showExpr(b) ++ ")"
  }

export func main() -> () ! {IO} {
