import abc
from dataclasses import dataclass
from typing import Callable, List

class Tree(abc.ABC):
    """Abstract base class for a Tree."""
    pass

@dataclass(frozen=True)
class Leaf(Tree):
    """Leaf node with an integer value."""
    value: int

@dataclass(frozen=True)
class Node(Tree):
    """Internal node with a value and left/right subtrees."""
    left: Tree
    value: int
    right: Tree

def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively apply a function to all values in a tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )
    # This path should be unreachable with correct types
    raise TypeError(f"Unsupported tree type: {type(tree)}")

def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """Perform an in-order fold over the tree's values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        left_acc = foldTree(fn, acc, tree.left)
        value_acc = fn(left_acc, tree.value)
        right_acc = foldTree(fn, value_acc, tree.right)
        return right_acc
    raise TypeError(f"Unsupported tree type: {type(tree)}")

def treeToList(tree: Tree) -> List[int]:
    """Convert a tree to a list using in-order traversal."""
    if isinstance(tree, Leaf):
        return [tree.value]
    elif isinstance(tree, Node):
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)
    raise TypeError(f"Unsupported tree type: {type(tree)}")

def treeDepth(tree: Tree) -> int:
    """Calculate the depth of a tree."""
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))
    raise TypeError(f"Unsupported tree type: {type(tree)}")

def main() -> None:
    """Main function to demonstrate tree operations."""
    example_tree: Tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # In-order values: [1, 2, 3, 4, 5, 6, 7]
    in_order_values = treeToList(example_tree)
    print(in_order_values)

    # Doubled values: [2, 4, 6, 8, 10, 12, 14]
    doubled_tree = mapTree(lambda x: x * 2, example_tree)
    doubled_values = treeToList(doubled_tree)
    print(doubled_values)

    # Sum of all values: 28
    total_sum = foldTree(lambda acc, val: acc + val, 0, example_tree)
    print(total_sum)

    # Tree depth: 3
    depth = treeDepth(example_tree)
    print(depth)

if __name__ == "__main__":
    main()

